using System.Text;

using CanonicalJson;

using TUF.Models;

using TUnit.Assertions;
using TUnit.Core;

namespace TUF.InteroperabilityTests;

/// <summary>
/// Tests that verify interoperability between the .NET TUF implementation
/// and other language implementations (Python, Go, Rust).
/// 
/// These tests ensure that:
/// 1. .NET can read and verify metadata generated by other implementations
/// 2. Other implementations can read and verify metadata generated by .NET
/// 3. Signature verification works across implementations
/// 4. JSON serialization is compatible across implementations
/// </summary>
public class CrossLanguageInteroperabilityTests
{
