    /// <summary>
    /// Sample targets metadata generated by Go-TUF to test cross-language compatibility.
    /// This represents realistic metadata that would be generated by the Go implementation.
    /// </summary>
    private static readonly string GoGeneratedTargetsMetadata = """
        {
          "signatures": [
            {
              "keyid": "a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2",
              "sig": "go_signature_placeholder_would_be_valid_base64_encoded_signature_here_123456789"
            }
          ],
          "signed": {
            "_type": "targets",
            "spec_version": "1.0.0",
            "version": 1,
            "expires": "2025-12-31T23:59:59Z",
            "targets": {
              "example-target.txt": {
                "length": 1024,
                "hashes": {
                  "sha256": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
                }
              },
              "another-file.bin": {
                "length": 2048,
                "hashes": {
                  "sha256": "a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3",
                  "sha512": "cf83e1357eefb8bdf1542850d66d8007d620e4050b5715dc83f4a921d36ce9ce47d0d13c5d85f2b0ff8318d2877eec2f63b931bd47417a81a538327af927da3e"
                }
              }
