    [Test]
    public async Task CanDeserializePythonGeneratedRootMetadata()
    {
        // Test that we can successfully deserialize metadata generated by Python-TUF
        Console.WriteLine("Testing deserialization of Python-generated root metadata...");
        
        try
        {
            var metadata = CanonicalJson.Serializer.Deserialize<Metadata<Root>, MetadataProxy.De<Root>>(PythonGeneratedRootMetadata);
            
            // Verify the basic structure
            await Assert.That(metadata).IsNotNull();
            await Assert.That(metadata.Signed).IsNotNull();
            await Assert.That(metadata.Signatures).IsNotNull();
            await Assert.That(metadata.Signatures).HasCount().EqualTo(1);
            
            // Verify metadata content
            var root = metadata.Signed;
            await Assert.That(root.Type).IsEqualTo("root");
            await Assert.That(root.SpecVersion).IsEqualTo("1.0.0");
            await Assert.That(root.Version).IsEqualTo(1);
            await Assert.That(root.Keys).HasCount().EqualTo(1);
            await Assert.That(root.Roles).IsNotNull();
            
            // Verify roles structure
            await Assert.That(root.Roles.Root).IsNotNull();
            await Assert.That(root.Roles.Targets).IsNotNull();
            await Assert.That(root.Roles.Snapshot).IsNotNull();
            await Assert.That(root.Roles.Timestamp).IsNotNull();
            
            Console.WriteLine("✅ Successfully parsed Python-generated root metadata");
            Console.WriteLine($"   Root version: {root.Version}");
            Console.WriteLine($"   Keys count: {root.Keys.Count}");
            Console.WriteLine($"   Signatures count: {metadata.Signatures.Count}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"❌ Failed to parse Python-generated metadata: {ex.Message}");
            throw;
        }
    }

    [Test]
    public async Task CanDeserializeGoGeneratedTargetsMetadata()
    {
        // Test that we can successfully deserialize metadata generated by Go-TUF
        Console.WriteLine("Testing deserialization of Go-generated targets metadata...");
        
        try
        {
            var metadata = CanonicalJson.Serializer.Deserialize<Metadata<Targets>, MetadataProxy.De<Targets>>(GoGeneratedTargetsMetadata);
            
            // Verify the basic structure
            await Assert.That(metadata).IsNotNull();
            await Assert.That(metadata.Signed).IsNotNull();
            await Assert.That(metadata.Signatures).IsNotNull();
            await Assert.That(metadata.Signatures).HasCount().EqualTo(1);
            
            // Verify metadata content
            var targets = metadata.Signed;
            await Assert.That(targets.Type).IsEqualTo("targets");
            await Assert.That(targets.SpecVersion).IsEqualTo("1.0.0");
            await Assert.That(targets.Version).IsEqualTo(1);
            await Assert.That(targets.TargetMap).HasCount().EqualTo(2);
            
            // Verify target entries
            await Assert.That(targets.TargetMap.ContainsKey("example-target.txt")).IsTrue();
            await Assert.That(targets.TargetMap.ContainsKey("another-file.bin")).IsTrue();
            
            var exampleTarget = targets.TargetMap["example-target.txt"];
            await Assert.That(exampleTarget.Length).IsEqualTo(1024);
            await Assert.That(exampleTarget.Hashes.ContainsKey("sha256")).IsTrue();
            
            var anotherFile = targets.TargetMap["another-file.bin"];
            await Assert.That(anotherFile.Length).IsEqualTo(2048);
            await Assert.That(anotherFile.Hashes.ContainsKey("sha256")).IsTrue();
            await Assert.That(anotherFile.Hashes.ContainsKey("sha512")).IsTrue();
            
            Console.WriteLine("✅ Successfully parsed Go-generated targets metadata");
            Console.WriteLine($"   Targets version: {targets.Version}");
            Console.WriteLine($"   Target files count: {targets.TargetMap.Count}");
            Console.WriteLine($"   Signatures count: {metadata.Signatures.Count}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"❌ Failed to parse Go-generated metadata: {ex.Message}");
            throw;
        }
    }

    [Test]
    public async Task CanonicalJsonOutputIsCompatibleAcrossImplementations()
    {
        // Test that our canonical JSON output is compatible with other implementations
        Console.WriteLine("Testing canonical JSON compatibility across implementations...");
        
        // Create a simple key object
        var key = new Key
        {
            KeyType = "ed25519",
            Scheme = "ed25519", 
            KeyVal = new KeyValue
            {
                Public = "abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890"
            }
        };
        
        // Serialize with our canonical JSON implementation
        var jsonBytes = CanonicalJson.Serializer.Serialize(key);
        var jsonString = Encoding.UTF8.GetString(jsonBytes);
        
        Console.WriteLine($"Generated canonical JSON: {jsonString}");
        
        // Verify basic canonical JSON properties
        // 1. No unnecessary whitespace
        await Assert.That(jsonString.Contains("  ")).IsFalse(); // No double spaces
        await Assert.That(jsonString.Contains("\n")).IsFalse(); // No newlines
        await Assert.That(jsonString.Contains("\t")).IsFalse(); // No tabs
        
        // 2. Properties should be in lexicographic order (this is crucial for compatibility)
        var keyTypeIndex = jsonString.IndexOf("\"keytype\"");
        var keyvalIndex = jsonString.IndexOf("\"keyval\"");
        var schemeIndex = jsonString.IndexOf("\"scheme\"");
        
        await Assert.That(keyTypeIndex).IsLessThan(keyvalIndex);
        await Assert.That(keyvalIndex).IsLessThan(schemeIndex);
        
        // 3. Verify we can round-trip the JSON
        var deserialized = CanonicalJson.Serializer.Deserialize<Key>(jsonString);
        await Assert.That(deserialized.KeyType).IsEqualTo(key.KeyType);
        await Assert.That(deserialized.Scheme).IsEqualTo(key.Scheme);
        await Assert.That(deserialized.KeyVal.Public).IsEqualTo(key.KeyVal.Public);
        
        Console.WriteLine("✅ Canonical JSON format is compatible with TUF specification requirements");
        Console.WriteLine($"   JSON length: {jsonString.Length} characters");
        Console.WriteLine($"   Properties are in lexicographic order: keytype < keyval < scheme");
    }

    [Test]
    public async Task KeyIdCalculationIsConsistentAcrossImplementations()
    {
        // Test that our key ID calculation produces results consistent with other implementations
        Console.WriteLine("Testing key ID calculation consistency across implementations...");
        
        // Use the same key data from the conformance tests
        var key = new Key
        {
            KeyType = "ecdsa",
            Scheme = "ecdsa-sha2-nistp256",
            KeyVal = new KeyValue
            {
                Public = "-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEJwsHFs2fOgFNIFnX7g+q5Q+ZIdBt\n0sZSWIgYQPjnA7GPirxVsRt/CG8OR9ueMZ43RDlbw3BuN7dd3Dpd+0pKTQ==\n-----END PUBLIC KEY-----\n"
            }
        };
        
        var keyId = key.GetKeyId();
        var expectedKeyId = "9c77c0b277eab2fb88d41546d25c82a57286e86969bee8187dedc195e900fb8f";
        
        Console.WriteLine($"Calculated Key ID: {keyId}");
        Console.WriteLine($"Expected Key ID: {expectedKeyId}");
        
        // This should match the key ID calculated by Python-TUF and Go-TUF
        await Assert.That(keyId).IsEqualTo(expectedKeyId);
        
        // Also test that the canonical JSON representation is consistent
        var canonicalJsonBytes = CanonicalJson.Serializer.Serialize(key);
        var canonicalJsonString = Encoding.UTF8.GetString(canonicalJsonBytes);
        
        Console.WriteLine($"Canonical JSON: {canonicalJsonString}");
        
        // The JSON should be deterministic and parseable
        await Assert.That(canonicalJsonString).IsNotNull();
        await Assert.That(canonicalJsonString.Length).IsGreaterThan(0);
        
        // Should be able to deserialize back to the same object
        var deserializedKey = CanonicalJson.Serializer.Deserialize<Key>(canonicalJsonString);
        await Assert.That(deserializedKey.GetKeyId()).IsEqualTo(expectedKeyId);
        
        Console.WriteLine("✅ Key ID calculation is consistent with other TUF implementations");
    }

    [Test]
    public async Task MetadataSignedBytesCalculationIsCompatible()
    {
        // Test that our signed bytes calculation for metadata matches other implementations
        Console.WriteLine("Testing metadata signed bytes calculation compatibility...");
        
        var root = new Root
        {
            Type = "root",
            SpecVersion = "1.0.0",
            Version = 1,
            Expires = DateTimeOffset.Parse("2025-12-31T23:59:59Z"),
            Keys = new Dictionary<string, Key>
            {
                ["test-key"] = new Key
                {
                    KeyType = "ed25519",
                    Scheme = "ed25519",
                    KeyVal = new KeyValue { Public = "test-public-key-data" }
                }
            },
            Roles = new Roles
            {
                Root = new RoleKeys { KeyIds = ["test-key"], Threshold = 1 },
                Targets = new RoleKeys { KeyIds = ["test-key"], Threshold = 1 },
                Snapshot = new RoleKeys { KeyIds = ["test-key"], Threshold = 1 },
                Timestamp = new RoleKeys { KeyIds = ["test-key"], Threshold = 1 }
            },
            ConsistentSnapshot = false
        };
        
        var metadata = new Metadata<Root>
        {
            Signed = root,
            Signatures = []
        };
        
        // Get the signed bytes using our implementation
        var signedBytes = metadata.GetSignedBytes();
        var signedString = Encoding.UTF8.GetString(signedBytes);
        
        Console.WriteLine($"Signed bytes length: {signedBytes.Length}");
        Console.WriteLine($"First 100 chars: {signedString.Substring(0, Math.Min(100, signedString.Length))}");
        
        // Verify the signed bytes are canonical JSON
        await Assert.That(signedBytes).IsNotNull();
        await Assert.That(signedBytes.Length).IsGreaterThan(0);
        
        // Should be able to deserialize the signed bytes back to the same object
        var deserializedRoot = CanonicalJson.Serializer.Deserialize<Root>(signedString);
        await Assert.That(deserializedRoot.Type).IsEqualTo(root.Type);
        await Assert.That(deserializedRoot.Version).IsEqualTo(root.Version);
        await Assert.That(deserializedRoot.Keys.Count).IsEqualTo(root.Keys.Count);
        
        Console.WriteLine("✅ Metadata signed bytes calculation produces canonical JSON");
        Console.WriteLine($"   Canonical JSON is {signedBytes.Length} bytes");
        Console.WriteLine($"   Round-trip serialization successful");
    }
}